window.SITE_SEARCH_INDEX = [{"url": "index.html", "page": "דף הבית", "title": "מתקרבים לגיל 18?", "text": "מתקרבים לגיל 18? המעבר מקצבת ילד נכה לבגרות כולל כמה מסלולי זכויות שונים. כאן אפשר להבין מה רלוונטי לך, מה כדאי לבדוק ומה הצעד הבא. בדיקה קצרה – מה רלוונטי לי? לכל הזכויות"}, {"url": "index.html", "page": "דף הבית", "title": "מה רלוונטי אליי?", "text": "מה רלוונטי אליי? ענו על כמה שאלות קצרות ונציג מה כדאי לבדוק מה הגיל? בחר/י 16–17 17–18 18 ומעלה האם מתקבלת כיום קצבת ילד נכה? בחר/י כן לא לא בטוח/ה האם יש צורך בעזרה ביום־יום או בהשגחה? בחר/י כן לא לא בטוח/ה מהו המעמד התעסוקתי? בחר/י שכיר/ה עצמאי/ת / עסק לא עובד/ת האם יש עניין בלימודי מקצוע או בהשתלבות בעבודה? בחר/י כן לא לא בטוח/ה הצג מה רלוונטי לי ←"}, {"url": "index.html", "page": "דף הבית", "title": "מה כדאי לבדוק?", "text": "מה כדאי לבדוק? בחרו נושא והמשיכו להסבר קצר וברור. 👤 1. נכות כללית מה משתנה בגיל 18 ואיך בודקים זכאות. איך מתבצע המעבר? תנאי זכאות מה בודקים? טפסים, מחשבונים וקישורים לבדיקה ← 🤲 2. שירותים מיוחדים (שר״ם) סיוע למי שזקוק לעזרה או להשגחה. מה זה שר״ם? מי עשוי להיות זכאי? מה בודקים? איך מגישים? לבדיקה ← 🎓 3. שיקום מקצועי לימודים, הכשרה וליווי לעבודה. למי זה מתאים? מה אפשר לקבל? תנאי זכאות איך מתחילים? לבדיקה ← 🧮 4. דמי ביטוח בגיל 17.5–18.5 מה משלמים, מי פטור ומה משתנה בגיל 18. שכיר/ה עצמאי/ת לא עובד/ת לפני גיוס/שירות מקבל/ת קצבה לבדיקה ←"}, {"url": "index.html", "page": "דף הבית", "title": "1. נכות כללית", "text": "1. נכות כללית מה משתנה בגיל 18 ואיך בודקים זכאות. איך מתבצע המעבר? תנאי זכאות מה בודקים? טפסים, מחשבונים וקישורים לבדיקה ←"}, {"url": "index.html", "page": "דף הבית", "title": "2. שירותים מיוחדים (שר״ם)", "text": "2. שירותים מיוחדים (שר״ם) סיוע למי שזקוק לעזרה או להשגחה. מה זה שר״ם? מי עשוי להיות זכאי? מה בודקים? איך מגישים? לבדיקה ←"}, {"url": "index.html", "page": "דף הבית", "title": "3. שיקום מקצועי", "text": "3. שיקום מקצועי לימודים, הכשרה וליווי לעבודה. למי זה מתאים? מה אפשר לקבל? תנאי זכאות איך מתחילים? לבדיקה ←"}, {"url": "index.html", "page": "דף הבית", "title": "4. דמי ביטוח בגיל 17.5–18.5", "text": "4. דמי ביטוח בגיל 17.5–18.5 מה משלמים, מי פטור ומה משתנה בגיל 18. שכיר/ה עצמאי/ת לא עובד/ת לפני גיוס/שירות מקבל/ת קצבה לבדיקה ←"}, {"url": "index.html", "page": "דף הבית", "title": "מה הצעד הבא שלי?", "text": "מה הצעד הבא שלי? לא בטוחים מאיפה להתחיל? התחילו מהבדיקה הקצרה, עברו למסלול הרלוונטי ורכזו את המסמכים הדרושים. בכל עמוד פנימי תמצאו “מה לבדוק עכשיו” וקישורים למקור הרשמי."}, {"url": "index.html", "page": "דף הבית", "title": "קישורים חשובים", "text": "קישורים חשובים כל הקישורים שהופיעו בקובץ שהעלית, מחוברים לעמודים הרשמיים. ✓ הטבות למקבלי קצבת נכות בדיקת זכויות במוסדות וארגונים אחרים לכל הקישורים וההסברים ←"}, {"url": "index.html", "page": "דף הבית", "title": "העמוד היה נוח וברור?", "text": "העמוד היה נוח וברור? משוב קצר יעזור לנו להבין מה חסר ומה כדאי לשפר, במיוחד בשימוש בנייד."}, {"url": "disability.html", "page": "נכות כללית", "title": "מעבר מקצבת ילד נכה לנכות כללית", "text": "מעבר מקצבת ילד נכה לנכות כללית המעבר אינו “המשך אוטומטי” של קצבת ילד נכה. נכות כללית בודקת בעיקר את הנכות הרפואית ואת ההשפעה על היכולת לעבוד ולהשתכר."}, {"url": "disability.html#transition", "page": "נכות כללית", "title": "איך מתבצע המעבר?", "text": "איך מתבצע המעבר? חשוב: לפני גיל 18 הביטוח הלאומי שולח באופן יזום תביעות לנכות כללית ו/או לשירותים מיוחדים, אך צריך להחזיר את התביעה עם מסמכים רפואיים עדכניים כדי לאפשר בדיקה ורצף זכויות. קצבת ילד נכה משולמת עד גיל 18 ו־31 יום. בתקופת המעבר משולם הסכום הגבוה יותר לפי הכללים: אם קצבת ילד נכה גבוהה יותר, היא עשויה להמשיך עד גיל 18 ו־90 יום; אם נכות כללית ו/או שר״ם גבוהים יותר, התשלום יכול לעבור אליהם מגיל 18 ו־31 יום."}, {"url": "disability.html#eligibility", "page": "נכות כללית", "title": "תנאי זכאות מרכזיים לנכות כללית", "text": "תנאי זכאות מרכזיים לנכות כללית 1 גיל ותושבות בדיקה לפי תנאי הביטוח הלאומי לנכות כללית. 2 הכנסה מעבודה נבדקת הכנסה מעבודה בתקופה שקדמה לתביעה ובהתאם לסכום הסף המעודכן. 3 נכות רפואית ככלל: 60% לפחות, או 40% לפחות כאשר יש כמה ליקויים וליקוי אחד הוא 25% לפחות. 4 אי־כושר נבדק אם עקב הנכות היכולת לעבוד או להשתכר נפגעה ב־50% לפחות, ונקבעת דרגת אי־כושר. לא להתבלבל: אחוז נכות רפואית אינו זהה לדרגת אי־כושר. שני הדברים נבדקים בנפרד."}, {"url": "disability.html#process", "page": "נכות כללית", "title": "מה כדאי לעשות לפני גיל 18?", "text": "מה כדאי לעשות לפני גיל 18? לאסוף מסמכים רפואיים עדכניים המתארים את המצב הנוכחי. לעבור על הטפסים שנשלחו מהביטוח הלאומי ולא להשאיר אותם ללא מענה. לבדוק במקביל גם שר״ם אם יש צורך בעזרת הזולת או בהשגחה. אם יש עבודה או עסק – לבדוק כיצד ההכנסה והמעמד משפיעים על הזכאות ועל דמי הביטוח."}, {"url": "disability.html#links", "page": "נכות כללית", "title": "קישורים שימושיים", "text": "קישורים שימושיים מעבר מקצבת ילד נכה לקצבת נכות ביטוח לאומי – ההסבר הרשמי על תקופת המעבר פתיחה ↗ תנאי זכאות לנכות כללית ביטוח לאומי פתיחה ↗ מחשבונים, ספר המבחנים, תעודת נכה והטבות כל הקישורים מהקובץ שהעלית לרשימה ← 📄 טפסים ואישורים – ביטוח לאומי מרכז הטפסים הרשמי פתיחה ↗"}, {"url": "disability.html", "page": "נכות כללית", "title": "העמוד היה נוח וברור?", "text": "העמוד היה נוח וברור? משוב קצר יעזור לנו להבין מה חסר ומה כדאי לשפר, במיוחד בשימוש בנייד."}, {"url": "special-services.html", "page": "שירותים מיוחדים (שר״ם)", "title": "שירותים מיוחדים (שר״ם)", "text": "שירותים מיוחדים (שר״ם) שר״ם הוא מסלול נפרד מנכות כללית. הוא מתמקד בעיקר בצורך בעזרה של אדם אחר בפעולות יום־יום או בצורך בהשגחה."}, {"url": "special-services.html#what", "page": "שירותים מיוחדים (שר״ם)", "title": "מה זה שר״ם?", "text": "מה זה שר״ם? קצבה לשירותים מיוחדים מיועדת, בין היתר, לאנשים מגיל 18 ועד גיל פרישה הזקוקים לעזרה רבה של אדם אחר בפעולות היום־יום או להשגחה מתמדת למניעת סכנה לעצמם או לאחרים. הבדל חשוב: נכות כללית בודקת בעיקר כושר השתכרות. שר״ם בודק בעיקר תפקוד, תלות בעזרה והשגחה. לכן ייתכן שאדם יהיה רלוונטי למסלול אחד, לשניהם, או לאף אחד מהם."}, {"url": "special-services.html#who", "page": "שירותים מיוחדים (שר״ם)", "title": "מי עשוי להיות זכאי?", "text": "מי עשוי להיות זכאי? תושב/ת ישראל מגיל 18 ועד גיל פרישה, בכפוף לתנאים. מי שמקבל קצבת נכות כללית – נבדקים גם ספי הנכות הרפואית הרלוונטיים. גם מי שאינו מקבל קצבת נכות עשוי להיות זכאי אם מתקיימים תנאים רפואיים ותפקודיים מתאימים. קיימים תנאים נוספים לגבי הכנסה מעבודה, שהייה במוסד וקצבאות אחרות."}, {"url": "special-services.html#check", "page": "שירותים מיוחדים (שר״ם)", "title": "מה בודקים בפועל?", "text": "מה בודקים בפועל? 1 לבישה עד כמה האדם זקוק לעזרה כדי להתלבש ולהתפשט. 2 אכילה הצורך בעזרה באכילה ושתייה. 3 רחצה והיגיינה יכולת להתקלח ולבצע היגיינה אישית. 4 ניידות בבית יכולת להתנייד בתוך סביבת המגורים. 5 השגחה האם קיימת סכנה שמחייבת השגחה מתמדת."}, {"url": "special-services.html#apply", "page": "שירותים מיוחדים (שר״ם)", "title": "איך מגישים?", "text": "איך מגישים? ממלאים תביעה ומצרפים מסמכים רפואיים עדכניים. התביעה עוברת לבדיקת רופא ביטוח לאומי. אם לא ניתן לקבוע זכאות על סמך המסמכים, תיתכן הזמנה לוועדה או בדיקת תלות. אפשר להיעזר בשירות “יד מכוונת” להכנה ללא תשלום. עמוד שירותים מיוחדים ביטוח לאומי – תהליך, תביעה ומעקב פתיחה ↗ תנאי הזכאות המלאים ביטוח לאומי פתיחה ↗ 📄 טפסים ואישורים – ביטוח לאומי מרכז הטפסים הרשמי פתיחה ↗"}, {"url": "special-services.html", "page": "שירותים מיוחדים (שר״ם)", "title": "העמוד היה נוח וברור?", "text": "העמוד היה נוח וברור? משוב קצר יעזור לנו להבין מה חסר ומה כדאי לשפר, במיוחד בשימוש בנייד."}, {"url": "vocational-rehab.html", "page": "שיקום מקצועי", "title": "שיקום מקצועי", "text": "שיקום מקצועי מסלול שמטרתו לסייע לאדם עם מוגבלות להשתלב בעבודה באמצעות אבחון, לימודים, הכשרה, תמיכה וסיוע בהשמה."}, {"url": "vocational-rehab.html#important", "page": "שיקום מקצועי", "title": "הנקודה החשובה ביותר", "text": "הנקודה החשובה ביותר אפשר להיות זכאי לשיקום מקצועי גם בלי לקבל קצבת נכות. לפי ביטוח לאומי, נקודת הכניסה המרכזית היא קביעה של לפחות 20% נכות רפואית, יחד עם תנאים נוספים."}, {"url": "vocational-rehab.html#eligibility", "page": "שיקום מקצועי", "title": "תנאי זכאות עיקריים", "text": "תנאי זכאות עיקריים תושב/ת ישראל שמלאו לו/ה 18 ועדיין לא הגיע/ה לגיל פרישה. נקבעו לפחות 20% נכות רפואית על ידי ועדה רפואית של הביטוח הלאומי. עקב ההשלכות התפקודיות של הנכות אין יכולת לחזור לעבודה הקודמת או לעבודה מתאימה אחרת. יש צורך בהכשרה מקצועית כדי להשתלב בעולם העבודה. קיימת התאמה לתהליך שיקום שבסופו ניתן להשתלב בעבודה מפרנסת בשוק החופשי."}, {"url": "vocational-rehab.html#receive", "page": "שיקום מקצועי", "title": "מה אפשר לקבל?", "text": "מה אפשר לקבל? 1 אבחון תעסוקתי בירור כישורים, מגבלות וכיוון מקצועי מתאים. 2 לימודים והכשרה לימודים מקצועיים או אקדמיים, בהתאם לתכנית שאושרה. 3 סיוע במהלך הלימודים במקרים המתאימים – אביזרי לימוד, תמיכות והוצאות הקשורות לתכנית. 4 סיוע בהשתלבות בעבודה ליווי והכוונה לקראת השתלבות תעסוקתית."}, {"url": "vocational-rehab.html#start", "page": "שיקום מקצועי", "title": "איך מתחילים?", "text": "איך מתחילים? הצעד הראשון הוא לבדוק אם קיימת קביעה רפואית מתאימה ואם יש צורך אמיתי בהכשרה לשם השתלבות בעבודה. לאחר מכן פונים למחלקת השיקום בביטוח הלאומי לבדיקת התאמה ובניית תכנית. תנאי זכאות לשיקום מקצועי ביטוח לאומי פתיחה ↗ 📄 טפסים ואישורים – ביטוח לאומי מרכז הטפסים הרשמי פתיחה ↗"}, {"url": "vocational-rehab.html", "page": "שיקום מקצועי", "title": "העמוד היה נוח וברור?", "text": "העמוד היה נוח וברור? משוב קצר יעזור לנו להבין מה חסר ומה כדאי לשפר, במיוחד בשימוש בנייד."}, {"url": "insurance.html", "page": "דמי ביטוח", "title": "דמי ביטוח בגיל 17.5–18.5", "text": "דמי ביטוח בגיל 17.5–18.5 גיל 18 הוא נקודת שינוי במעמד הביטוחי. לא נכון להניח שכל צעיר משלם אותו דבר: צריך לבדוק אם הוא שכיר, עצמאי, לא עובד, לפני גיוס/שירות או מקבל קצבה."}, {"url": "insurance.html#before", "page": "דמי ביטוח", "title": "לפני גיל 18", "text": "לפני גיל 18"}, {"url": "insurance.html", "page": "דמי ביטוח", "title": "שכיר/ה", "text": "שכיר/ה המעסיק מדווח ומשלם את דמי הביטוח. לעובד שטרם מלאו לו 18 אין ניכוי של דמי ביטוח לאומי ובריאות מהשכר לפי טבלת השכירים הרלוונטית; המעסיק משלם שיעור מופחת."}, {"url": "insurance.html", "page": "דמי ביטוח", "title": "עצמאי/ת", "text": "עצמאי/ת אם הצעיר עונה להגדרת “עובד עצמאי” של הביטוח הלאומי, הוא משלם שיעורי ביטוח לאומי מופחתים מאוד. מי שטרם מלאו לו 18 פטור מדמי ביטוח בריאות. פתיחת עסק לבדה אינה קובעת מעמד “עצמאי”. ביטוח לאומי בודק שעות עבודה והכנסה. נכון ל־2026: 20 שעות שבועיות בממוצע; או הכנסה חודשית של 6,885 ₪ ומעלה; או 12 שעות שבועיות והכנסה של 2,065 ₪ ומעלה."}, {"url": "insurance.html#after", "page": "דמי ביטוח", "title": "מה משתנה מגיל 18?", "text": "מה משתנה מגיל 18? מגיל 18 דמי הביטוח הלאומי ודמי ביטוח הבריאות נקבעים לפי המעמד וההכנסה, אלא אם חל פטור. מעמד מה קורה? מה חשוב לבדוק? שכיר/ה המעסיק מנכה את חלק העובד ומשלם גם את חלק המעסיק. שכר, גיל, פטור אפשרי עקב קצבת נכות. עצמאי/ת העצמאי משלם בעצמו לפי הכנסה ומעמד. רישום בזמן, הגדרת עצמאי, הכנסה מזערית ושיעורים. לא עובד/ת עשויה להיות חובת תשלום מינימלית. לימודים, גיוס, שירות לאומי, הכנסות ופטורים. לפני גיוס/שירות ייתכן פטור עד תחילת השירות. מועד שירות, האם עובד/ת והאם קיימת הכנסה אחרת. מקבל/ת קצבת נכות ייתכנו פטורים או אופן גבייה שונה. דרגת אי־כושר, עבודה, ביטוח לאומי מול ביטוח בריאות."}, {"url": "insurance.html#exemptions", "page": "דמי ביטוח", "title": "פטורים שכדאי לבדוק", "text": "פטורים שכדאי לבדוק לפני גיוס לצה״ל או שירות לאומי/אזרחי: מי שמלאו לו 18 ויתחיל שירות לפני גיל 21 עשוי להיות פטור בתקופת ההמתנה, אם אינו עובד ואין לו הכנסה מעל הסף שנקבע. מקבל קצבת נכות: עשוי להיות פטור מדמי ביטוח לאומי בתנאים מסוימים. חשוב לבדוק בנפרד את דמי ביטוח הבריאות. תלמיד/סטודנט: קיימים מסלולי חיוב/תעריף שונים לפי המעמד; לא מניחים אוטומטית פטור."}, {"url": "insurance.html#branches", "page": "דמי ביטוח", "title": "לאילו ענפים מבוטחים?", "text": "לאילו ענפים מבוטחים? לפני גיל 18: הכיסוי של עובד צעיר מצומצם יותר, ובמרכזו ענף נפגעי עבודה. מגיל 18: נפתח כיסוי רחב יותר בהתאם למעמד. שכיר ועצמאי אינם מבוטחים בדיוק באותם ענפים; למשל, עצמאי אינו מבוטח באבטלה כמו שכיר."}, {"url": "insurance.html#links", "page": "דמי ביטוח", "title": "קישורים רשמיים", "text": "קישורים רשמיים שיעורי דמי ביטוח – שכירים ביטוח לאומי פתיחה ↗ שיעורי דמי ביטוח – עצמאים ביטוח לאומי פתיחה ↗ מי נחשב עובד עצמאי? הגדרה לפי שעות והכנסה פתיחה ↗ מי צריך לשלם דמי ביטוח בריאות? כולל פטור לפני גיוס/שירות פתיחה ↗ 📄 טפסים ואישורים – ביטוח לאומי מרכז הטפסים הרשמי פתיחה ↗"}, {"url": "insurance.html", "page": "דמי ביטוח", "title": "העמוד היה נוח וברור?", "text": "העמוד היה נוח וברור? משוב קצר יעזור לנו להבין מה חסר ומה כדאי לשפר, במיוחד בשימוש בנייד."}, {"url": "links.html", "page": "קישורים וכלי עזר", "title": "קישורים, מחשבונים וכלי עזר", "text": "קישורים, מחשבונים וכלי עזר ריכזתי כאן את כל הקישורים שהופיעו בקובץ “קישורים” שהעלית. הקישורים מחוברים לעמודים הרשמיים של הביטוח הלאומי."}, {"url": "links.html#uploaded", "page": "קישורים וכלי עזר", "title": "כל הקישורים מהקובץ שהעלית", "text": "כל הקישורים מהקובץ שהעלית 📄 מסמכים רפואיים שמומלץ לצרף מחשבון ביטוח לאומי לפי אבחנה פתיחה ↗ 📘 ספר המבחנים רשימת ליקויים ואחוזי נכות לפי החוק פתיחה ↗ 🧮 חישוב נכות משוקללת מחשבון נכות רפואית משוקללת פתיחה ↗ 🧮 מחשבון סכום קצבת נכות חישוב משוער של סכום הקצבה פתיחה ↗ 🪪 תעודת נכה – זכאות והפקה מידע על הזכאות והטבות התעודה פתיחה ↗ ✓ הטבות למקבלי קצבת נכות בדיקת זכויות במוסדות וארגונים אחרים פתיחה ↗"}, {"url": "links.html#extra", "page": "קישורים וכלי עזר", "title": "קישורים משלימים שימושיים", "text": "קישורים משלימים שימושיים נכות כללית – דף ראשי ביטוח לאומי פתיחה ↗ שירותים מיוחדים – דף ראשי ביטוח לאומי פתיחה ↗ שיקום מקצועי – תנאי זכאות ביטוח לאומי פתיחה ↗ מעבר מילד נכה לנכות כללית ביטוח לאומי פתיחה ↗"}, {"url": "links.html", "page": "קישורים וכלי עזר", "title": "העמוד היה נוח וברור?", "text": "העמוד היה נוח וברור? משוב קצר יעזור לנו להבין מה חסר ומה כדאי לשפר, במיוחד בשימוש בנייד."}];